pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score is the residual left after placing the item.
    let mut score = post_residual as f64;

    // Reward a perfectly full bin.
    if post_residual == 0 {
        score -= 5.0;
    }

    // Penalize / reward based on how the residual compares to the mean residual.
    let residual_rel = (post_residual as f64) - mean_residual;
    if residual_rel > 0.0 {
        // Too much free space – modest penalty.
        score += residual_rel * 0.5;
    } else {
        // Less free space than average – slight reward.
        score += residual_rel * 0.2; // residual_rel is negative here
    }

    // 2‑step lookahead: consider the next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let progress = step_index as f64 / total_items as f64;
        let diff_weight = if progress > 0.8 { 2.5 } else { 2.0 };
        score += diff * diff_weight;
    }

    // Penalize if many bins are open – encourages packing into fewer bins.
    if open_bins_count > 1 {
        score += 10.0 * ((open_bins_count as f64) - 1.0);
    }

    // If this is the only bin that can fit the item, add a small penalty
    // to favour opening a new bin when it would be better.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score += 5.0;
    }

    // Special handling for a brand‑new empty bin candidate.
    if bin_residual == bin_capacity {
        // Compute what the score would be if we opened a new bin.
        let new_post = bin_capacity - item_size;
        let mut new_score = new_post as f64;

        if next_item_size > 0 {
            let new_diff = (new_post as i64 - next_item_size as i64).abs() as f64;
            let progress = step_index as f64 / total_items as f64;
            let new_diff_weight = if progress > 0.8 { 2.5 } else { 2.0 };
            new_score += new_diff * new_diff_weight;
        }

        if new_post == 0 {
            new_score -= 5.0;
        }

        let new_residual_rel = (new_post as f64) - mean_residual;
        if new_residual_rel > 0.0 {
            new_score += new_residual_rel * 0.5;
        } else {
            new_score += new_residual_rel * 0.2;
        }

        // If opening a new bin would be strictly better, bias towards it.
        if new_score < score {
            score = new_score - 2.0; // slight extra advantage for a new bin
        }
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let bin_cap_f = bin_capacity as f64;

    // Tight fit is rewarded more strongly early in the stream
    let residual_norm = post_residual as f64 / bin_cap_f;
    score -= (1.0 - progress).powi(2) * residual_norm * bin_cap_f;

    // Prefer bins whose residual is close to the mean residual
    let mean_norm = mean_residual / bin_cap_f;
    score -= (mean_norm - residual_norm).powi(2) * progress * bin_cap_f;

    // If the next item is large, penalize bins that would leave insufficient space
    if next_item_size > 0 {
        let gap = if post_residual < next_item_size {
            (next_item_size - post_residual) as f64
        } else {
            0.0
        };
        score += gap.powi(2) * (1.0 - progress);
    }

    // When only one bin can fit the item, lower the score
    let fit_log = ((fitting_bins_count as f64).ln() + 1.0);
    score -= fit_log * 10.0;

    // Using many open bins is slightly discouraged
    score -= open_bins_count as f64 * 0.1;

    // Prefer opening a new bin only late in the stream
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score: remaining space after placing the item
    let mut score = post_residual as f64;

    // Aggressive 2‑step lookahead: favor bins whose leftover space is close to the next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        // Reward bins that leave a residual close to the next item
        score -= (100.0 - diff) * 0.5;

        // Penalize bins that cannot accommodate the next item
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.2;
        }
    }

    // Compare the residual to the mean residual of all open bins.
    // Bins whose residual is closer to the mean are preferred (less fragmentation).
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score -= mean_diff * 0.3;

    // If this is the only bin that can fit the item, force its selection.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // For a brand‑new empty bin: open it only if it would leave a reasonable amount of space.
    if bin_residual == bin_capacity {
        if post_residual as f64 > mean_residual * 1.5 {
            score += (post_residual as f64 - mean_residual * 1.5) * 0.8;
        }
    }

    // As we approach the end of the stream, tighten packing by slightly favoring bins that
    // reduce the number of open bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= open_bins_count as f64 * 0.05;
    }

    score
}

