pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score is the remaining space after placing the item
    let mut score = post_residual as f64;

    // Progress factor grows from 1.0 at the start to 2.0 at the end of the stream
    let progress = step_index as f64 / total_items as f64;
    let progress_factor = 1.0 + progress;

    // Penalize dead space that cannot accommodate the next item
    if next_item_size > 0 && next_item_size > post_residual {
        let dead = (next_item_size - post_residual) as f64;
        score += dead * 2.0 * progress_factor;
    }

    // Strongly reward the only bin that can fit the item
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Open-bins pressure: more open bins increase the penalty
    score += (open_bins_count as f64) * 1.0 * progress_factor;

    // Encourage bins whose residual is close to the current mean residual
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Basic residual after placement
    let mut score = post_residual as f64;

    // Progress in the stream (0.0 → 1.0)
    let progress = step_index as f64 / total_items as f64;

    // Residual ratios
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    let mean_ratio = mean_residual / bin_capacity as f64;
    let diff_residual = (residual_ratio - mean_ratio).abs();

    // Penalize large leftover space and deviation from mean residual
    score += 5.0 * residual_ratio;
    score += 3.0 * diff_residual * bin_capacity as f64;

    // Look‑ahead: reward if next item fits, penalize if it won't
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits – reward, more so later in the stream
            score -= 10.0 * progress;
        } else {
            // next item won’t fit – penalize, more so earlier
            score += 10.0 * (1.0 - progress);
        }
    }

    // If this bin is the only one that can take the item, strongly reward it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Avoid opening a new bin when many are already open unless necessary
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 20.0;
    }

    // Encourage closing open bins by penalizing the count
    score += 0.5 * open_bins_count as f64;

    // Slight reward for tighter packing (smaller post‑residual)
    score -= 2.0 * residual_ratio * 100.0;

    score
}
